insert into public.talk_topics (id, "group", format, text, deeper, a, b, topics, status) values
  ('talk-001', 'moral', 'agree', 'It is okay to lie to someone you love to protect them.', 'Where is the line between protecting someone and controlling them?', null, null, '{}'::text[], 'approved'),
  ('talk-002', 'moral', 'agree', 'If a friend cheats, you have to tell their partner.', 'Does it change if the partner is also your friend?', null, null, '{}'::text[], 'approved'),
  ('talk-003', 'moral', 'agree', 'You can forgive someone who never said sorry.', 'Who does the forgiving help, them or you?', null, null, '{}'::text[], 'approved'),
  ('talk-004', 'moral', 'agree', 'People should be judged by their usual self, not their worst moment.', 'Is there a mistake so big it outweighs everything else?', null, null, '{}'::text[], 'approved'),
  ('talk-005', 'moral', 'agree', 'Keeping a friend''s secret is always the loyal thing to do.', 'What secret would make you break your word?', null, null, '{}'::text[], 'approved'),
  ('talk-006', 'moral', 'agree', 'A person can be good without believing in anything.', 'What keeps a person good when nobody is watching?', null, null, array['religion']::text[], 'approved'),
  ('talk-007', 'moral', 'agree', 'You should return a wallet full of cash with no ID in it.', 'Would your answer change if you were broke this week?', null, null, '{}'::text[], 'approved'),
  ('talk-008', 'moral', 'agree', 'It is fine to cut someone off after one big betrayal.', 'What would a person have to do to earn a second chance?', null, null, '{}'::text[], 'approved'),
  ('talk-009', 'moral', 'agree', 'It is wrong to take credit for a group project you barely worked on.', 'What if everyone else agreed to let you take it?', null, null, '{}'::text[], 'approved'),
  ('talk-010', 'moral', 'agree', 'Telling a white lie to avoid hurting someone is kinder than the truth.', 'When did a white lie last make things worse?', null, null, '{}'::text[], 'approved'),
  ('talk-011', 'moral', 'agree', 'You should always tell a friend when they are making a mistake.', 'Has a friend ever been right to tell you, even when it hurt?', null, null, '{}'::text[], 'approved'),
  ('talk-012', 'moral', 'think', 'Is it worse to hurt someone on purpose or by not caring?', 'Which one have you been guilty of more often?', null, null, '{}'::text[], 'approved'),
  ('talk-013', 'moral', 'agree', 'Cheating on a test is okay if the test is unfair.', 'Who decides when a rule is unfair?', null, null, '{}'::text[], 'approved'),
  ('talk-014', 'fate', 'agree', 'We do not choose who we fall for. It just happens.', 'Then why do some people keep falling for the same type?', null, null, '{}'::text[], 'approved'),
  ('talk-015', 'fate', 'agree', 'Success is mostly luck.', 'What was the luckiest break you ever got?', null, null, '{}'::text[], 'approved'),
  ('talk-016', 'fate', 'think', 'If you could see how your life ends, would you look?', 'What if it turned out ordinary? Would that be a relief or a letdown?', null, null, array['death']::text[], 'approved'),
  ('talk-017', 'fate', 'agree', 'Everything happens for a reason.', 'Name something that hurt at the time and made sense later.', null, null, '{}'::text[], 'approved'),
  ('talk-018', 'fate', 'agree', 'There is one person out there for everyone.', 'If so, what are the odds you have already met yours?', null, null, '{}'::text[], 'approved'),
  ('talk-019', 'fate', 'think', 'Is there anything after we die?', 'How does your answer change the way you live?', null, null, array['religion', 'death']::text[], 'approved'),
  ('talk-020', 'fate', 'think', 'If you replayed your life from the start, how much would change?', 'What is the one thing you would keep exactly as it was?', null, null, '{}'::text[], 'approved'),
  ('talk-021', 'fate', 'agree', 'Where you were born decides most of how your life goes.', 'What one thing did your starting point give you that others did not get?', null, null, '{}'::text[], 'approved'),
  ('talk-022', 'fate', 'think', 'If you could ask one person from your past one question and get the whole truth, who and what?', 'Why have you never asked it?', null, null, '{}'::text[], 'approved'),
  ('talk-023', 'fate', 'agree', 'Meeting the right person at the wrong time is the saddest thing there is.', 'Has it happened to you?', null, null, '{}'::text[], 'approved'),
  ('talk-024', 'fate', 'think', 'What is one thing that was pure luck and changed everything for you?', 'Do you think you would have found another way?', null, null, '{}'::text[], 'approved'),
  ('talk-025', 'self', 'think', 'If every part of you was slowly replaced, would you still be you?', 'Which part of you could never be replaced?', null, null, '{}'::text[], 'approved'),
  ('talk-026', 'self', 'agree', 'You are the same person online as in real life.', 'Who has met only one of your two versions?', null, null, '{}'::text[], 'approved'),
  ('talk-027', 'self', 'agree', 'People can really change.', 'Who in your life actually did, and what made the difference?', null, null, '{}'::text[], 'approved'),
