  ('talk-041', 'society', 'think', 'What will people in 50 years find strange about how we live?', 'What do we do today that they will judge us for most?', null, null, '{}'::text[], 'approved'),
  ('talk-042', 'society', 'agree', 'Remote work is better for people than working in an office.', 'What do you lose when nobody is in the same room?', null, null, '{}'::text[], 'approved'),
