  ('talk-051', 'reflect', 'think', 'Which small decision changed your life the most?', 'What would your life look like if you had decided the other way?', null, null, '{}'::text[], 'approved'),
  ('talk-052', 'reflect', 'think', 'What are you proud of that nobody around you knows about?', 'Why have you kept it to yourself?', null, null, '{}'::text[], 'approved'),
  ('talk-053', 'reflect', 'think', 'What is the best advice you ever ignored?', 'What did ignoring it cost you, or save you?', null, null, '{}'::text[], 'approved'),
  ('talk-054', 'reflect', 'think', 'Who has been the biggest influence on who you are today?', 'Have you ever told them?', null, null, '{}'::text[], 'approved'),
  ('talk-055', 'reflect', 'think', 'What did you want to be when you were ten, and what happened?', 'Is there a piece of it you could still do?', null, null, '{}'::text[], 'approved'),
  ('talk-056', 'reflect', 'think', 'What is something you used to be afraid of that does not scare you now?', 'What took the fear away?', null, null, '{}'::text[], 'approved'),
  ('talk-057', 'reflect', 'think', 'What habit would you give up first if you could?', 'What stops you?', null, null, '{}'::text[], 'approved'),
  ('talk-058', 'reflect', 'think', 'What is the best thing that happened to you this year?', 'Who would you want to share it with?', null, null, '{}'::text[], 'approved'),
  ('talk-059', 'takes', 'agree', 'A hotdog is a sandwich.', 'So what is the one thing that makes a sandwich a sandwich?', null, null, '{}'::text[], 'approved'),
  ('talk-060', 'takes', 'agree', 'Leaving a group chat without saying anything is rude.', 'What is the politest way to leave one?', null, null, '{}'::text[], 'approved'),
