  ('talk-078', 'dilemma', 'ab', 'Would you rather have a job you love that pays little, or one you hate that pays well?', 'How much more would it take to make you switch?', 'Love it, low pay', 'Hate it, high pay', array['money', 'career']::text[], 'approved'),
