  ('talk-086', 'dilemma', 'ab', 'Would you rather marry someone your family loves and you like, or someone you love and your family cannot stand?', 'Who is in the room when you decide, you or your family?', 'Family loves them', 'You love them', '{}'::text[], 'approved'),
  ('talk-087', 'dilemma', 'ab', 'Would you rather know the day you will die, or never know?', 'What is the first thing you would change?', 'Know the day', 'Never know', array['death']::text[], 'approved'),
  ('talk-088', 'dilemma', 'ab', 'Would you rather speak every language, or play every instrument perfectly?', 'Where is the first place you would use it?', 'Every language', 'Every instrument', '{}'::text[], 'approved'),
